INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Artworks Portrait Session on Thursday Mornings', 'Miami Figure Drawing Saturday Morning Group', 'General Networking', 'Thursday morning portrait session is a 3-hour, not-instructed, single pose of a male or female clothed model. Artists pay $20 cash per', 'Thursday morning portrait session is a 3-hour, not-instructed, single pose of a male or female clothed model. Artists pay $20 cash per session. Bring your own drawing or water based painting materials – no solvent based oil paints allowed. Easels are available in the studio. Models are paid $70 for posing in one pose, for 3 hours with a 8 minute break every 20 minutes. To get booked as a model call or text: Gene Page at 786.523.4858 or Alex Mirrington 786-847-3709. More info: https://www.meetup.com/miami-figure-drawing-saturday-morning-group/events/316709301/', '2026-10-15T10:00:00-04:00', 'Bird Road Arts District', '4180 SW 74th Court', 'Miami', 'FL', '', 25.74, -80.31, 'Miami Figure Drawing Saturday Morning Group', 1, false, '$20', 'live', 'meetup', 'https://www.meetup.com/miami-figure-drawing-saturday-morning-group/events/316709301/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
