INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Saturday afternoon figure session', 'Miami Figure Drawing Saturday Morning Group', 'General Networking', 'Saturday afternoon figure drawing session from 2 to 4 pm. Life drawing male or female model will pose for 2-minute gestures through a', 'Saturday afternoon figure drawing session from 2 to 4 pm. Life drawing male or female model will pose for 2-minute gestures through a 20-minute long pose. No instruction. Bring your own drawing paper and drawing or painting media. No turpentine or paint thinners, please. Easels, drawing boards and chairs available for you to use. $20 cash only. More info: https://www.meetup.com/miami-figure-drawing-saturday-morning-group/events/316738612/', '2026-10-17T14:00:00-04:00', 'Bird Road Arts District', '4180 SW 74th Court', 'Miami', 'FL', '', 25.74, -80.31, 'Miami Figure Drawing Saturday Morning Group', 1, false, '$20', 'live', 'meetup', 'https://www.meetup.com/miami-figure-drawing-saturday-morning-group/events/316738612/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
