INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Looking Ahead: What Will Shape the Products We Build?', 'Product Lunch Orlando', 'General Networking', 'What should product managers be paying attention to now that could influence the products we build tomorrow? For our December Product', 'What should product managers be paying attention to now that could influence the products we build tomorrow? For our December Product Lunch, we’re looking ahead and comparing what we’re seeing across different companies, customers, and industries. We’ll talk about changing customer expectations, emerging technologies, new competitors, shifts in markets and business models, economic pressures, regulation, and other signals that could influence what’s we build and how our products create value. More info: https://www.meetup.com/product-lunch-orlando/events/316141407/', '2026-12-11T12:30:00-05:00', 'The Tap Room at Dubsdread Country Club', '549 West Par St.', 'Orlando', 'FL', '', 28.56, -81.35, 'Product Lunch Orlando', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/product-lunch-orlando/events/316141407/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Business of Product: Building Products That Make Business Sense', 'Product Lunch Orlando', 'General Networking', 'A great product has to solve a customer problem. It also has to work as a business. For our March Product Lunch, we’re digging into the', 'A great product has to solve a customer problem. It also has to work as a business. For our March Product Lunch, we’re digging into the commercial side of product management and the decisions that determine whether a product can actually succeed in the market. We’ll talk about pricing, profitability, market size, competitive positioning, business models, revenue, margins, investment decisions, and how product managers make the case for where the business should invest. How involved should More info: https://www.meetup.com/product-lunch-orlando/events/316141529/', '2027-03-19T12:30:00-04:00', 'Sixty Vines', '7760 Sand Lake Rd,', 'Orlando', 'FL', '', 28.56, -81.35, 'Product Lunch Orlando', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/product-lunch-orlando/events/316141529/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Supper, Songs & New Friends: Taco Night', 'Real Connection Palm Beach', 'General Networking', 'Come on your own for a small, welcoming taco supper in Boynton Beach. We''ll eat together, get to know one another, then move to the living', 'Come on your own for a small, welcoming taco supper in Boynton Beach. We''ll eat together, get to know one another, then move to the living room for a relaxed round of favorite recorded songs. If you''d like, bring one song you enjoy and tell us a little about why you chose it. Listening is just as welcome. No singing, performing, or music expertise needed. We''ll have make-your-own tacos, including a vegetarian option. Please message me about any dietary needs when you RSVP so I can plan the More info: https://www.meetup.com/real-connection-palm-beach/events/316773436/', '2026-10-16T19:00:00-04:00', 'Boynton Beach', 'Boynton Beach, FL, USA', 'Boynton Beach', 'FL', '', 26.52, -80.11, 'Real Connection Palm Beach', 4, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-connection-palm-beach/events/316773436/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Art Walk & Coffee in Delray', 'Real Connection Palm Beach', 'General Networking', 'Come on your own for an easy afternoon of art, conversation, and coffee in downtown Delray. We''ll explore Art on the Square together, share', 'Come on your own for an easy afternoon of art, conversation, and coffee in downtown Delray. We''ll explore Art on the Square together, share what catches our eye, and get to know one another along the way. You don''t need to know anything about art—curiosity is plenty. Meet at 1:00 p.m. outside the main entrance of Cornell Art Museum at Old School Square, 51 N Swinton Ave, Delray Beach. Look for Otto, the Real Connection Palm Beach host. We''ll wander the outdoor art show together, sometimes in More info: https://www.meetup.com/real-connection-palm-beach/events/316921101/', '2026-11-08T13:00:00-05:00', '51 North Swinton Avenue', '51 N Swinton Ave, Delray Beach, FL 33444, USA', 'Delray Beach', 'FL', '33444', 26.4625665906, -80.073059385725, 'Real Connection Palm Beach', 4, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-connection-palm-beach/events/316921101/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
