INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ONLINE EVENT: Sell Smart, Defer the Tax: A Practical Guide to 1031 Exchanges', 'Real Estate Investing - Free Education & Mentoring (Naples)', 'Real Estate Meetings', 'Real estate investors are looking beyond their local markets for stronger cash flow, greater affordability, and long-term growth, and many', 'Real estate investors are looking beyond their local markets for stronger cash flow, greater affordability, and long-term growth, and many are using 1031 Exchanges to strategically reposition their portfolios. Join us for an educational session designed for investors who want to better understand how a 1031 Exchange may help them **sell qualifying investment property, potentially defer capital gains taxes, and reinvest in new opportunities** across the country. Featured speaker Aristotle More info: https://www.meetup.com/real-estate-investing-free-education-mentoring-naples-fl/events/316913788/', '2026-12-01T20:00:00-05:00', 'Online event', 'Online event', 'Naples', 'FL', '', 26.14, -81.8, 'Real Estate Investing - Free Education & Mentoring (Naples)', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/real-estate-investing-free-education-mentoring-naples-fl/events/316913788/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
